CREATE TABLE INSTRUCTOR (INSTRUCTOR_ID NUMBER(8,0) ,SALUTATION VARCHAR2(5)  ,FIRST_NAME VARCHAR2(25)  ,LAST_NAME VARCHAR2(25)  ,STREET_ADDRESS VARCHAR2(50)  ,ZIP VARCHAR2(5)  ,PHONE VARCHAR2(15)  ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE GRADE (STUDENT_ID NUMBER(8,0) ,SECTION_ID NUMBER(8,0) ,GRADE_TYPE_CODE CHAR(2) ,GRADE_CODE_OCCURRENCE NUMBER(38,0) ,NUMERIC_GRADE NUMBER(3,0) DEFAULT 0 ,COMMENTS VARCHAR2(2000)  ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE GRADE_CONVERSION  (LETTER_GRADE VARCHAR2(2)  ,GRADE_POINT NUMBER(3,2) DEFAULT 0  ,MAX_GRADE NUMBER(3,0)  ,MIN_GRADE NUMBER(3,0)  ,CREATED_BY VARCHAR2(30)  ,CREATED_DATE DATE  ,MODIFIED_BY VARCHAR2(30)  ,MODIFIED_DATE DATE   );
CREATE TABLE GRADE_TYPE  (GRADE_TYPE_CODE CHAR(2) ,DESCRIPTION VARCHAR2(50) ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE GRADE_TYPE_WEIGHT (SECTION_ID NUMBER(8,0) ,GRADE_TYPE_CODE CHAR(2) ,NUMBER_PER_SECTION NUMBER(3,0) ,PERCENT_OF_FINAL_GRADE NUMBER(3,0) ,DROP_LOWEST CHAR(1) ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE SECTION (SECTION_ID NUMBER(8,0) ,COURSE_NO NUMBER(8,0) ,SECTION_NO NUMBER(3,0) ,START_DATE_TIME DATE  ,LOCATION VARCHAR2(50)  ,INSTRUCTOR_ID NUMBER(8,0) ,CAPACITY NUMBER(3,0)  ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE COURSE  (COURSE_NO NUMBER(38,0) ,DESCRIPTION VARCHAR2(50) ,COST NUMBER(9,2) ,PREREQUISITE NUMBER(8,0)  ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE ENROLLMENT (STUDENT_ID NUMBER(8,0) ,SECTION_ID NUMBER(8,0) ,ENROLL_DATE DATE ,FINAL_GRADE NUMBER(3,0)  ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE STUDENT (STUDENT_ID NUMBER(8,0) ,SALUTATION VARCHAR2(5)  ,FIRST_NAME VARCHAR2(25)  ,LAST_NAME VARCHAR2(25) ,STREET_ADDRESS VARCHAR2(50)  ,ZIP VARCHAR2(5) ,PHONE VARCHAR2(15)  ,EMPLOYER VARCHAR2(50)  ,REGISTRATION_DATE DATE ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );
CREATE TABLE ZIPCODE (ZIP VARCHAR2(5) ,CITY VARCHAR2(25)  ,STATE VARCHAR2(2)  ,CREATED_BY VARCHAR2(30) ,CREATED_DATE DATE ,MODIFIED_BY VARCHAR2(30) ,MODIFIED_DATE DATE );

COMMENT ON TABLE INSTRUCTOR IS 'Profile information for an instructor.';
COMMENT ON COLUMN INSTRUCTOR.INSTRUCTOR_ID IS 'The unique ID for an instructor.';
COMMENT ON COLUMN INSTRUCTOR.ZIP IS 'The unique zip code number for this instructor.';
COMMENT ON COLUMN INSTRUCTOR.PHONE IS 'The phone number for this instructor including area code.';

COMMENT ON TABLE GRADE IS 'The individual grades a student received for a particular section(class).';
COMMENT ON COLUMN GRADE.STUDENT_ID IS 'The unique ID for the student.';
COMMENT ON COLUMN GRADE.SECTION_ID IS 'The unique ID for a section.';
COMMENT ON COLUMN GRADE.GRADE_TYPE_CODE IS 'The code which identifies a category of grade.';
COMMENT ON COLUMN GRADE.GRADE_CODE_OCCURRENCE IS 'The sequence number of one grade type for one section. For example, there could be multiple assignments numbered 1,2,3, etc.';
COMMENT ON COLUMN GRADE.NUMERIC_GRADE IS 'Numeric grade value, i.e. 70,75.';
COMMENT ON COLUMN GRADE.COMMENTS IS 'Instructor''s comments on this grade.';

COMMENT ON TABLE GRADE_TYPE IS 'Lookup table of a grade types (code) and its description.';
COMMENT ON COLUMN GRADE_TYPE.GRADE_TYPE_CODE IS 'The unique code which identifies a category of grade, i.e. MT, HW.';
COMMENT ON COLUMN GRADE_TYPE.DESCRIPTION IS 'The description for this code, i.e. Midterm, Homework.';

COMMENT ON TABLE GRADE_CONVERSION IS 'Converts a number grade to a letter grade.';
COMMENT ON COLUMN GRADE_CONVERSION.LETTER_GRADE IS 'The unique grade as a letter (A, A-, B, B+, etc.).';
COMMENT ON COLUMN GRADE_CONVERSION.GRADE_POINT IS 'The number grade on a scale from 0 (F) to 4 (A).';
COMMENT ON COLUMN GRADE_CONVERSION.MAX_GRADE IS 'The highest grade number which makes this letter grade.';
COMMENT ON COLUMN GRADE_CONVERSION.MIN_GRADE IS 'The lowest grade number which makes this letter grade.';

COMMENT ON TABLE GRADE_TYPE_WEIGHT IS 'Information on how the final grade for a particular section is computed.  For example, the midterm constitutes 50%, the quiz 10% and the final examination 40% of the final grade.';
COMMENT ON COLUMN GRADE_TYPE_WEIGHT.SECTION_ID IS 'The unique section ID for a section.';
COMMENT ON COLUMN GRADE_TYPE_WEIGHT.GRADE_TYPE_CODE IS 'The code which identifies a category of grade.';
COMMENT ON COLUMN GRADE_TYPE_WEIGHT.NUMBER_PER_SECTION IS 'How many of these grade types can be used in this section.  That is, there may be 3 quizzes.';
COMMENT ON COLUMN GRADE_TYPE_WEIGHT.PERCENT_OF_FINAL_GRADE IS 'The precentage this category of grade contributes to the final grade.';
COMMENT ON COLUMN GRADE_TYPE_WEIGHT.DROP_LOWEST IS 'Is the lowest grade in this type removed when determining the final grade? (Y;N)';

COMMENT ON TABLE SECTION IS 'Information for an individual section (class) of a particular course.';
COMMENT ON COLUMN SECTION.SECTION_ID IS 'The unique ID for a section.';
COMMENT ON COLUMN SECTION.COURSE_NO IS 'The course number for which this is a section.';
COMMENT ON COLUMN SECTION.SECTION_NO IS 'The individual section number within this course.';
COMMENT ON COLUMN SECTION.START_DATE_TIME IS 'The date and time on which this section meets.';
COMMENT ON COLUMN SECTION.LOCATION IS 'The meeting room for the section.';
COMMENT ON COLUMN SECTION.INSTRUCTOR_ID IS 'The ID number of the instructor who teaches this section.';
COMMENT ON COLUMN SECTION.CAPACITY IS 'The maximum number of students allowed in this section.';

COMMENT ON TABLE COURSE IS 'Information for a course.';
COMMENT ON COLUMN COURSE.COURSE_NO IS 'The unique ID for a course.';
COMMENT ON COLUMN COURSE.DESCRIPTION IS 'The full name for this course.';
COMMENT ON COLUMN COURSE.COST IS 'The dollar amount charged for enrollment in this course.';
COMMENT ON COLUMN COURSE.PREREQUISITE IS 'The ID number of the course which must be taken as a prerequisite to this course.';

COMMENT ON TABLE ENROLLMENT IS 'Information for a student registered for a particular section (class).';
COMMENT ON COLUMN ENROLLMENT.STUDENT_ID IS 'The unique ID for a student.';
COMMENT ON COLUMN ENROLLMENT.SECTION_ID IS 'The unique ID for a section.';
COMMENT ON COLUMN ENROLLMENT.ENROLL_DATE IS 'The date this student registered for this section.';
COMMENT ON COLUMN ENROLLMENT.FINAL_GRADE IS 'The final grade given to this student for all work in this section (class).';

COMMENT ON TABLE STUDENT IS 'Profile information for a student.';
COMMENT ON COLUMN STUDENT.STUDENT_ID IS 'The unique ID for a student.';
COMMENT ON COLUMN STUDENT.ZIP IS 'The postal zip code for this student.';
COMMENT ON COLUMN STUDENT.PHONE IS 'The phone number for this student including area code.';
COMMENT ON COLUMN STUDENT.EMPLOYER IS 'The name of the company where this student is employed.';
COMMENT ON COLUMN STUDENT.REGISTRATION_DATE IS 'The date this student registered in the program.';

COMMENT ON TABLE ZIPCODE IS 'City, state and zip code information.';
COMMENT ON COLUMN ZIPCODE.ZIP IS 'The zip code number, unique for a city and state.';
COMMENT ON COLUMN ZIPCODE.CITY IS 'The city name for this zip code.';
COMMENT ON COLUMN ZIPCODE.STATE IS 'The postal abbreviation for the US state.';

CREATE INDEX INST_ZIP_FK_I ON INSTRUCTOR (ZIP);
CREATE INDEX GR_GRTW_FK_I ON GRADE (SECTION_ID  ,GRADE_TYPE_CODE);
CREATE INDEX GRTW_GRTYP_FK_I ON GRADE_TYPE_WEIGHT (GRADE_TYPE_CODE);
CREATE INDEX SECT_CRSE_FK_I ON SECTION (COURSE_NO);
CREATE INDEX SECT_INST_FK_I ON SECTION (INSTRUCTOR_ID);
CREATE INDEX CRSE_CRSE_FK_I ON COURSE (PREREQUISITE);
CREATE INDEX ENR_SECT_FK_I ON ENROLLMENT (SECTION_ID);
CREATE INDEX STU_ZIP_FK_I ON STUDENT (ZIP);









 

ALTER TABLE INSTRUCTOR ADD CONSTRAINT INST_MODFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT INST_INSTRUCTOR_ID_NNULL CHECK ("INSTRUCTOR_ID" IS NOT NULL) ADD CONSTRAINT INST_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT INST_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT INST_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL);
ALTER TABLE GRADE ADD CONSTRAINT GR_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT GR_STUDENT_ID_NNULL CHECK ("STUDENT_ID" IS NOT NULL) ADD CONSTRAINT GR_SECTION_ID_NNULL CHECK ("SECTION_ID" IS NOT NULL) ADD CONSTRAINT GR_GRADE_TYPE_CODE_NNULL CHECK ("GRADE_TYPE_CODE" IS NOT NULL) ADD CONSTRAINT GR_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT GR_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT GR_GRADE_CODE_OCCURRENCE_NNULL CHECK ("GRADE_CODE_OCCURRENCE" IS NOT NULL) ADD CONSTRAINT GR_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL);
ALTER TABLE GRADE_TYPE ADD CONSTRAINT GRTYP_DESCRIPTION_NNULL CHECK ("DESCRIPTION" IS NOT NULL) ADD CONSTRAINT GRTYP_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT GRTYP_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT GRTYP_GRADE_TYPE_CODE_NNULL CHECK ("GRADE_TYPE_CODE" IS NOT NULL) ADD CONSTRAINT GRTYP_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT GRTYP_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT GRTYP_GRADE_TYPE_CODE_LENGTH CHECK (LENGTH(grade_type_code)=2);
ALTER TABLE GRADE_CONVERSION ADD CONSTRAINT GRCON_MAX_GRADE_NNULL CHECK ("MAX_GRADE" IS NOT NULL) ADD CONSTRAINT GRCON_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT GRCON_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT GRCON_GRADE_POINT_NNULL CHECK ("GRADE_POINT" IS NOT NULL) ADD CONSTRAINT GRCON_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT GRCON_LETTER_GRADE_NNULL CHECK ("LETTER_GRADE" IS NOT NULL) ADD CONSTRAINT GRCON_MIN_GRADE_NNULL CHECK ("MIN_GRADE" IS NOT NULL) ADD CONSTRAINT GRCON_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL);
ALTER TABLE GRADE_TYPE_WEIGHT ADD CONSTRAINT GRTW_NUMBER_PER_SECTION_NNULL CHECK ("NUMBER_PER_SECTION" IS NOT NULL) ADD CONSTRAINT GRTW_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT GRTW_PCT_OF_FINAL_GRADE_NNULL CHECK ("PERCENT_OF_FINAL_GRADE" IS NOT NULL) ADD CONSTRAINT GRTW_GRADE_TYPE_CODE_NNULL CHECK ("GRADE_TYPE_CODE" IS NOT NULL) ADD CONSTRAINT GRTW_SECTION_ID_NNULL CHECK ("SECTION_ID" IS NOT NULL) ADD CONSTRAINT GRTW_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT GRTW_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT GRTW_DROP_LOWEST_NNULL CHECK ("DROP_LOWEST" IS NOT NULL) ADD CONSTRAINT GRTW_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL);
ALTER TABLE SECTION ADD CONSTRAINT SECT_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT SECT_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT SECT_SECTION_ID_NNULL CHECK ("SECTION_ID" IS NOT NULL) ADD CONSTRAINT SECT_SECTION_NO_NNULL CHECK ("SECTION_NO" IS NOT NULL) ADD CONSTRAINT SECT_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT SECT_INSTRUCTOR_ID_NNULL CHECK ("INSTRUCTOR_ID" IS NOT NULL) ADD CONSTRAINT SECT_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT SECT_COURSE_NO_NNULL CHECK ("COURSE_NO" IS NOT NULL);
ALTER TABLE COURSE ADD CONSTRAINT CRSE_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT CRSE_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT CRSE_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT CRSE_DESCRIPTION_NNULL CHECK ("DESCRIPTION" IS NOT NULL) ADD CONSTRAINT CRSE_COURSE_NO_NNULL CHECK ("COURSE_NO" IS NOT NULL) ADD CONSTRAINT CRSE_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL);  
ALTER TABLE ENROLLMENT ADD CONSTRAINT ENR_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT ENR_STUDENT_ID_NNULL CHECK ("STUDENT_ID" IS NOT NULL) ADD CONSTRAINT ENR_ENROLL_DATE_NNULL CHECK ("ENROLL_DATE" IS NOT NULL) ADD CONSTRAINT ENR_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT ENR_SECTION_ID_NNULL CHECK ("SECTION_ID" IS NOT NULL) ADD CONSTRAINT ENR_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT ENR_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL);  
ALTER TABLE STUDENT ADD CONSTRAINT STU_REGISTRATION_DATE_NNULL CHECK ("REGISTRATION_DATE" IS NOT NULL) ADD CONSTRAINT STU_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT STU_ZIP_NNULL CHECK ("ZIP" IS NOT NULL) ADD CONSTRAINT STU_LAST_NAME_NNULL CHECK ("LAST_NAME" IS NOT NULL) ADD CONSTRAINT STU_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT STU_STUDENT_ID_NNULL CHECK ("STUDENT_ID" IS NOT NULL) ADD CONSTRAINT STU_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL) ADD CONSTRAINT STU_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL);
ALTER TABLE ZIPCODE ADD CONSTRAINT ZIP_CREATED_BY_NNULL CHECK ("CREATED_BY" IS NOT NULL) ADD CONSTRAINT ZIP_MODIFIED_DATE_NNULL CHECK ("MODIFIED_DATE" IS NOT NULL) ADD CONSTRAINT ZIP_CREATED_DATE_NNULL CHECK ("CREATED_DATE" IS NOT NULL) ADD CONSTRAINT ZIP_ZIP_NNULL CHECK ("ZIP" IS NOT NULL) ADD CONSTRAINT ZIP_MODIFIED_BY_NNULL CHECK ("MODIFIED_BY" IS NOT NULL);

ALTER TABLE INSTRUCTOR ADD CONSTRAINT INST_PK PRIMARY KEY (INSTRUCTOR_ID);
ALTER TABLE GRADE ADD CONSTRAINT GR_PK PRIMARY KEY (STUDENT_ID  ,SECTION_ID  ,GRADE_TYPE_CODE  ,GRADE_CODE_OCCURRENCE);
ALTER TABLE GRADE_TYPE ADD CONSTRAINT GRTYP_PK PRIMARY KEY (GRADE_TYPE_CODE);
ALTER TABLE GRADE_CONVERSION ADD CONSTRAINT GRCON_PK PRIMARY KEY (LETTER_GRADE);
ALTER TABLE GRADE_TYPE_WEIGHT ADD CONSTRAINT GRTW_PK PRIMARY KEY (SECTION_ID  ,GRADE_TYPE_CODE);
ALTER TABLE SECTION ADD CONSTRAINT SECT_PK PRIMARY KEY (SECTION_ID);
ALTER TABLE COURSE ADD CONSTRAINT CRSE_PK PRIMARY KEY (COURSE_NO);
ALTER TABLE ENROLLMENT ADD CONSTRAINT ENR_PK PRIMARY KEY (STUDENT_ID  ,SECTION_ID);
ALTER TABLE STUDENT ADD CONSTRAINT STU_PK PRIMARY KEY (STUDENT_ID);
ALTER TABLE ZIPCODE ADD CONSTRAINT ZIP_PK PRIMARY KEY (ZIP);
ALTER TABLE SECTION ADD ( CONSTRAINT SECT_SECT2_UK UNIQUE (SECTION_NO  ,COURSE_NO));
ALTER TABLE INSTRUCTOR ADD CONSTRAINT  INST_ZIP_FK FOREIGN KEY (ZIP) REFERENCES ZIPCODE (ZIP);
ALTER TABLE GRADE ADD CONSTRAINT  GR_ENR_FK FOREIGN KEY (STUDENT_ID  ,SECTION_ID) REFERENCES ENROLLMENT (STUDENT_ID  ,SECTION_ID) ADD CONSTRAINT  GR_GRTW_FK FOREIGN KEY (SECTION_ID  ,GRADE_TYPE_CODE) REFERENCES GRADE_TYPE_WEIGHT (SECTION_ID  ,GRADE_TYPE_CODE);
ALTER TABLE GRADE_TYPE_WEIGHT ADD CONSTRAINT  GRTW_GRTYP_FK FOREIGN KEY (GRADE_TYPE_CODE) REFERENCES GRADE_TYPE  (GRADE_TYPE_CODE) ADD CONSTRAINT  GRTW_SECT_FK FOREIGN KEY (SECTION_ID) REFERENCES SECTION (SECTION_ID);
ALTER TABLE SECTION ADD CONSTRAINT  SECT_INST_FK FOREIGN KEY (INSTRUCTOR_ID) REFERENCES INSTRUCTOR (INSTRUCTOR_ID) ADD CONSTRAINT  SECT_CRSE_FK FOREIGN KEY (COURSE_NO) REFERENCES COURSE  (COURSE_NO);
ALTER TABLE COURSE ADD CONSTRAINT  CRSE_CRSE_FK FOREIGN KEY (PREREQUISITE) REFERENCES COURSE  (COURSE_NO);
ALTER TABLE ENROLLMENT ADD CONSTRAINT  ENR_STU_FK FOREIGN KEY (STUDENT_ID) REFERENCES STUDENT (STUDENT_ID) ADD CONSTRAINT  ENR_SECT_FK FOREIGN KEY (SECTION_ID) REFERENCES SECTION (SECTION_ID);
ALTER TABLE STUDENT ADD CONSTRAINT  STU_ZIP_FK FOREIGN KEY (ZIP) REFERENCES ZIPCODE (ZIP);
CREATE SEQUENCE INSTRUCTOR_ID_SEQ  INCREMENT BY 1  START WITH 112  NOMAXVALUE  MINVALUE 1  NOCYCLE  NOCACHE;
CREATE SEQUENCE SECTION_ID_SEQ  INCREMENT BY 1  START WITH 158  NOMAXVALUE  MINVALUE 1  NOCYCLE  NOCACHE;
CREATE SEQUENCE STUDENT_ID_SEQ  INCREMENT BY 1  START WITH 401  NOMAXVALUE  MINVALUE 1  NOCYCLE  NOCACHE;
CREATE SEQUENCE COURSE_NO_SEQ  INCREMENT BY 1  START WITH 452  NOMAXVALUE  MINVALUE 1  NOCYCLE  NOCACHE;
